/**
 * Golden reference charts (spec section 10). The owner supplies one JSON file
 * per chart in this folder, with values from Drik Panchang (Lahiri). Until then
 * every required case is it.todo. Values must never be generated by us.
 *
 * File format (tests/golden/<name>.json):
 * {
 *   "name": "Jaipur 1995",
 *   "source": "Drik Panchang, retrieved 2026-11-01",
 *   "input": { "birthUtc": "1995-08-14T01:12:00Z", "lat": 26.9124, "lng": 75.7873 },
 *   "expected": {
 *     "lagnaSign": "Leo",
 *     "planets": { "Sun": { "sign": "Cancer", "degree": 27.01 }, ... all 9 },
 *     "moonNakshatra": "Ashlesha", "moonPada": 4,
 *     "dasha": { "at": "2026-10-31", "mahadasha": "Ketu", "antardasha": "Venus" }
 *   }
 * }
 */
import { readdirSync, readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { computeChart } from "@/lib/astro/chart";
import { currentDasha } from "@/lib/astro/dasha";
import { SIGNS } from "@/lib/astro/tables/signs";
import { PLANETS } from "@/lib/astro/tables/planets";

interface Golden {
  name: string;
  source: string;
  input: { birthUtc: string; lat: number; lng: number };
  expected: {
    lagnaSign: string;
    planets: Record<string, { sign: string; degree: number }>;
    moonNakshatra: string;
    moonPada: number;
    dasha: { at: string; mahadasha: string; antardasha: string };
  };
}

/** Spec accuracy target: planet longitudes within 0.05° of the reference tool. */
const TOLERANCE_DEG = 0.05;

const files = readdirSync("tests/golden").filter((f) => f.endsWith(".json"));

describe("golden charts", () => {
  if (files.length === 0) {
    it.todo("owner supplies 20 golden charts from Drik Panchang (Lahiri)");
    it.todo("births before 1956 in Mumbai and Kolkata");
    it.todo("births during 1942–45 (wartime +06:30)");
    it.todo("a birth near midnight");
    it.todo("a birth near a Lagna sign change");
    it.todo("births in London, Dubai and New York (with DST)");
    it.todo("the section 4 example: 14 Aug 1995, 06:42, Jaipur");
    return;
  }

  for (const file of files) {
    const g = JSON.parse(readFileSync(`tests/golden/${file}`, "utf8")) as Golden;
    describe(`${g.name} (${file})`, () => {
      const chart = computeChart({ birthUtc: new Date(g.input.birthUtc), lat: g.input.lat, lng: g.input.lng, timeKnown: true });

      it("Lagna sign", () => {
        expect(SIGNS[chart.lagna!.sign]!.en).toBe(g.expected.lagnaSign);
      });

      for (const p of PLANETS) {
        it(`${p} sign and degree`, () => {
          const exp = g.expected.planets[p];
          expect(exp, `missing expected value for ${p}`).toBeDefined();
          expect(SIGNS[chart.planets[p].sign]!.en).toBe(exp!.sign);
          expect(Math.abs(chart.planets[p].degreeInSign - exp!.degree)).toBeLessThanOrEqual(TOLERANCE_DEG);
        });
      }

      it("Moon nakshatra and pada", () => {
        expect(chart.planets.Moon.nakshatra.name).toBe(g.expected.moonNakshatra);
        expect(chart.planets.Moon.nakshatra.pada).toBe(g.expected.moonPada);
      });

      it("Mahadasha / Antardasha", () => {
        const tree = chart.dasha.mahadashas.map((m) => ({
          lord: m.lord,
          start: new Date(m.start),
          end: new Date(m.end),
          antardashas: m.antardashas.map((a) => ({ lord: a.lord, start: new Date(a.start), end: new Date(a.end) })),
        }));
        const now = currentDasha(tree, new Date(g.expected.dasha.at))!;
        expect(now.mahadasha.lord).toBe(g.expected.dasha.mahadasha);
        expect(now.antardasha.lord).toBe(g.expected.dasha.antardasha);
      });
    });
  }
});
